        ("Python: bytes to hex?", "<code>b.hex()</code> or <code>binascii.hexlify(b)</code>"),
        ("Python: base64 decode with missing padding?", "<code>base64.b64decode(s + '=' * (-len(s) % 4))</code>"),
        ("Python: XOR bytes with a repeating key?", "<code>bytes(b ^ key[i % len(key)] for i, b in enumerate(data))</code>"),
        ("Python: all 4-letter lowercase combinations?", "<code>itertools.product(string.ascii_lowercase, repeat=4)</code>"),
        ("Python: md5 of bytes?", "<code>hashlib.md5(b).hexdigest()</code>"),
        ("Python: regex for flags like CTF{...} in bytes?", "<code>re.findall(rb'CTF\\{.*?\\}', data)</code>"),
        ("Python: HTTP session with cookies?", "<code>s = requests.Session(); s.post(url, data=...)</code>"),
        ("pwntools: connect and read until a prompt?", "<code>io = remote(h, p); io.recvuntil(b'&gt; ')</code>"),
        ("pwntools: pack a 64-bit address?", "<code>p64(addr)</code> (unpack: <code>u64</code>)"),
        ("pwntools: cyclic pattern and offset?", "<code>cyclic(200)</code> then <code>cyclic_find(value)</code>"),
        ("What is the oracle loop cost?", "Length × alphabet size queries (not alphabet^length).<br>img:s-brute.svg"),
        ("Why test a script on a known example first?", "So you know the transform is right before trusting it on real data."),
        ("z3: when do you use it?", "When a binary applies arithmetic/bitwise checks to your input; model them as constraints.<br>img:s-toolbox.svg"),
        ("Parse a pcap in Python?", "<code>scapy.all.rdpcap('f.pcap')</code>, then filter by layer (<code>TCP</code>, <code>Raw</code>)."),
        ("Bash: byte histogram of a file?", "<code>xxd -p f | fold -w2 | sort | uniq -c | sort -rn</code>"),
        ("Bash: find all flags recursively?", "<code>grep -rEo 'CTF\\{[^}]+\\}' .</code>"),
        ("Why print intermediate values?", "Most script bugs are wrong assumptions about the data."),
        ("Why use timeouts on network scripts?", "Services stall; timeouts keep your script from hanging and losing state."),
